sys_variable_value.value:
(function execute(inputs, outputs) {
    taskConfig = {
        assignment_group: null,
        body: {
            extra_vars: {
                change_order: inputs.task.number + "",
            },
        },
        certificate_task: inputs.task,
        description: null,
        force_host: null,
        ip_address: null,
        port: null,
        ansible_flow: null,
        resource_path: null,
        short_description: null,
        target_ci: null,
        task: inputs.task,
        target_ci: null,
    };
    try {
        if (["flow_a", "flow_b", "flow_c"].includes(inputs.force_flow)) {
            taskConfig.ansible_flow = inputs.force_flow;
        } else if (inputs.force_flow) {
            sendWorkNotes("Ignorando forçar fluxo inválido - " + inputs.force_flow);
        }

        // EDX Carlos Paiva - Em DEV o HOMO só foi liberada pelo Kleber/Lucas a URL autocert.capgv.intra.bnb
        if (gs.getProperty("instance_name") != "bnbprod") {
            sendWorkNotes(
                taskConfig.task,
                "*** Utilizando URL para ambiente de testes: autocert.capgv.intra.bnb ***",
            );
            taskConfig.force_host = "autocert.capgv.intra.bnb";
        }

        var ixTaskType = [
            "sn_disco_certmgmt_new_task",
            "sn_disco_certmgmt_renew_task",
        ].indexOf(taskConfig.task.sys_class_name + "");
        if (ixTaskType == 0) {
            newCertificate(taskConfig);
        } else if (ixTaskType == 1) {
            renewCertificate(taskConfig);
        } else {
            throw new Error(
                "Task de certificado de classe não suportada: " +
                taskConfig.task.number +
                taskConfig.task.sys_class_name,
            );
        }

        outputs.description = taskConfig.description;
        outputs.short_description = taskConfig.short_description;

        outputs.certificate_task = taskConfig.certificate_task;
        outputs.resource_path = taskConfig.resource_path;
        outputs.post_body = JSON.stringify(taskConfig.body);
        outputs.renewal_flow = taskConfig.ansible_flow;
        outputs.target_ci = taskConfig.target_ci;
        outputs.ip_address = taskConfig.ip_address;
        outputs.port = taskConfig.port;
        outputs.assignment_group = taskConfig.assignment_group;
    } catch (ex) {
        sendWorkNotes(taskConfig.task, "*** ERRO " + ex);
        throw new Error("EDX Dispara Job Ansible ERROR: " + ex);
    }
})(inputs, outputs);

function newCertificate(taskConfig) {
    taskConfig.commonName = taskConfig.task.subject_common_name;

    var ansibleCommonName = taskConfig.force_host
        ? taskConfig.force_host
        : taskConfig.commonName;

    if (!taskConfig.ansible_flow) {
        if (taskConfig.task.certificate_purpose == "external") {
            taskConfig.ansible_flow = "flow_a";
        } else {
            taskConfig.ansible_flow = "flow_b";
        }
        var san = taskConfig.task.subject_alternative_name.split(",");
        if (taskConfig.ansible_flow == "flow_a") {
            taskConfig.body.extra_vars.common_name = ansibleCommonName;
            taskConfig.body.extra_vars.urls = san;
            taskConfig.resource_path = "job_templates/13/launch/";
            taskConfig.assignment_group = inputs.external_group;
            taskConfig.short_description =
                "Criação de Certificado Externo Novo " + taskConfig.commonName;
        } else {
            taskConfig.body.extra_vars.certificado = ansibleCommonName;
            taskConfig.body.extra_vars.key_size = 2048;
            taskConfig.body.extra_vars.san = san;
            taskConfig.resource_path = "job_templates/254/launch/";
            taskConfig.assignment_group = inputs.install_group;
            taskConfig.short_description =
                "Criação de Certificado Interno Novo " + taskConfig.commonName;
        }
        taskConfig.description = taskConfig.short_description
    }
}

function renewCertificate(taskConfig) {
    var certificate = taskConfig.task.certificate;
    taskConfig.commonName = certificate.subject_common_name;
    var ansibleCommonName = taskConfig.force_host
        ? taskConfig.force_host
        : taskConfig.commonName;

    var installedCertificates = [];
    new global.GlideQuery("sn_disco_certmgmt_cmdb_installed_certificate")
        .where("certificate", certificate)
        .orderBy("source", "port")
        .select("source", "port")
        .forEach(function (inst) {
            installedCertificates.push(inst.source + ":" + inst.port);
        });

    var ipPort = installedCertificates.reduce(function (compat, ipPort) {
        if (!compat) {
            var ipPortArr = ipPort.split(":");
            if (["8443", "9443", "443"].includes(ipPortArr[1])) {
                compat = {
                    ip: ipPortArr[0],
                    port: parseInt(ipPortArr[1]),
                };
            }
        }
        return compat;
    }, null);

    if (!ipPort) {
        throw new Error(
            "Certificado não está instalado em porta compatível " +
            taskConfig.task.number +
            " instalações:\n" +
            installedCertificates.join("\n"),
        );
    }

    var hostTypes = [
        "cmdb_ci_lb_service",
        "cmdb_ci_win_server",
        "cmdb_ci_linux_server",
        "cmdb_ci_server",
        "cmdb_ci_web_site",
        "cmdb_ci_computer",
        "cmdb_ci_endpoint_http",
        "cmdb_ci_kubernetes_node",
        "cmdb_ci_kubernetes_pod",
        "cmdb_ci_vmware_instance",
    ];
    var hostCI;
    var F5Host;
    var found = 999;
    new global.GlideQuery("cmdb_ci")
        .where("ip_address", ipPort.ip)
        .where("sys_class_name", "IN", hostTypes)
        .select("sys_id", "sys_class_name")
        .forEach(function (ci) {
            var ix = hostTypes.indexOf(ci.sys_class_name);
            if (ix < found) {
                found = ix;
                hostCI = ci.sys_id;
                if (ix == 0) {
                    F5Host = hostCI;
                }
            }
        });
    if (!hostCI) {
        hostCi = new global.GlideQuery("cmdb_ci")
            .where("ip_address", ipPort.ip)
            .selectOne()
            .get().sys_id;
    }
    taskConfig.short_description =
        "Renovação de Certificado " + taskConfig.commonName;
    taskConfig.description =
        "Certificado " +
        taskConfig.commonName +
        " Instalado em:\n" +
        installedCertificates.join("\n");

    if (!taskConfig.ansible_flow) {
        if (certificate.u_ca_scope == "external") {
            taskConfig.ansible_flow = "flow_a";
        } else {
            if (F5Host) {
                taskConfig.ansible_flow = "flow_c";
            } else {
                taskConfig.ansible_flow = "flow_b";
            }
        }
    }

    if (taskConfig.ansible_flow == "flow_c") {
        // Cenario C - Renovação Completa - Certificado F5 - Job 65
        if (!ipPort) {
            throw new Error("Missing Target CI for 'C' Flow");
        }
        ipPort.ip = "10.6.0.10";
        taskConfig.body.extra_vars.f5_host = ipPort.ip;
        taskConfig.body.extra_vars.profile_name_client =
            "Client_" + ansibleCommonName;
        taskConfig.body.extra_vars.profile_name_server =
            "Server_" + ansibleCommonName;
        taskConfig.resource_path = "job_templates/65/launch/";
        taskConfig.assignment_group = inputs.install_group;
    } else {
        taskConfig.body.extra_vars.url =
            "https://" + ansibleCommonName + ":" + ipPort.port;
        if (taskConfig.ansible_flow == "flow_b") {
            // Cenario B - GERAR PKEY, CSR, Assinar CA e Exportar - Job 19
            taskConfig.resource_path = "job_templates/19/launch/";
            taskConfig.assignment_group = inputs.install_group;
        } else {
            // Cenario A - GERAR apenas PKEY e CSR - Job 15
            taskConfig.resource_path = "job_templates/15/launch";
            if (certificate.u_ca_scope == "internal") {
                taskConfig.assignment_group = inputs.internal_group;
            } else {
                taskConfig.assignment_group = inputs.external_group;
            }
        }
    }

    taskConfig.target_ci = hostCI;
    taskConfig.ip_address = ipPort.ip;
    taskConfig.port = parseInt(ipPort.port) + "";
}

function sendWorkNotes(taskId, notes) {
    var params = {
        task_id: taskId,
        work_notes: notes,
    };
    // Send work notes to task
    sn_fd.FlowAPI.getRunner()
        .action("sn_disco_certmgmt.update_cert_task_work_notes")
        .inBackground()
        .withInputs(params)
        .run();
}

