sys_variable_value.value:
(function execute(inputs, outputs) {
	// verifica erro em step anterior
	try {
		if (inputs.status_code != 201) {
			throw new Error('Status code da chamada Ansible = ' + inputs.status_code + ' mensagem=' + inputs.status_message);
		}
		// verifica erro REST
		if (inputs.error_code != 0) {
			throw new Error('Error code da chamada Ansible=' + inputs.error_code + ' mensagem=' + inputs.error_message);
		}

		// parse REST return - set output vars
		var body = JSON.parse(inputs.response_body);
		outputs.job_id = body.job;
		outputs.job_url = body.url;
		outputs.job_status = body.status;

		addWorkNotes(inputs.task, "Disparado Ansible Job " + body.name + " - " + outputs.job_id + " status " + outputs.job_status);

	} catch (err) {
		addWorkNotes(inputs.task, "Erro - " + err);
		throw 'EDX ' + err;
	}
})(inputs, outputs);

function addWorkNotes(taskId, message) {
	try {
		var inputs = {};
		inputs['task_id'] = taskId;
		inputs['work_notes'] = message;
		// Start Asynchronously
		sn_fd.FlowAPI.getRunner().action('sn_disco_certmgmt.update_cert_task_work_notes').inBackground().withInputs(inputs).run();
	} catch (ex) {
		throw ex;
	}
}

