sys_variable_value.value:
(function execute(inputs, outputs) {

    try {

        var result = sn_fd.FlowAPI.getRunner().action('sn_disco_certmgmt.bnb__obtem_grupos_a_partir_de_propriedades').inForeground().run();
        var actionOutput = result.getOutputs();

        // Get Outputs:
        // Note: outputs can only be retrieved when executing synchronously.
        outputs.certificados_externos = actionOutput['certificados_externos']; // Reference
        outputs.certificados_internos = actionOutput['certificados_internos']; // Reference
        outputs.instalacao_de_certificados = actionOutput['instalacao_de_certificados']; // Reference

    } catch (ex) {
        var message = ex.getMessage();
        gs.error(message);
    }

})(inputs, outputs);

